using Forjix.Application.Abstractions.Cash;
using Forjix.Application.Abstractions.Identity;
using Forjix.Application.Abstractions.Sales;
using Forjix.Application.Abstractions.Tenancy;
using Forjix.Application.Common;
using Forjix.Domain.Enums;
namespace Forjix.Application.Features.Cash; internal sealed class CashService(ITenantDatabaseResolver resolver, ICashStoreFactory factory, ICurrentUser current, TimeProvider clock) : ICashService { public async Task<CashSessionView?> GetCurrentAsync(CancellationToken ct = default) { var s = await Store(ct); await using (s) return await s.GetCurrentAsync(ct); } public async Task<CashSessionView> OpenAsync(OpenCashRequest r, CancellationToken ct = default) { if (r.OpeningAmount < 0) throw new RequestValidationException("Valor de abertura inválido."); var s = await Store(ct); await using (s) return await s.OpenAsync(User(), r.OpeningAmount, clock.GetUtcNow(), Ctx(), ct); } public Task<CashSessionView> SupplyAsync(CashOperationRequest r, CancellationToken ct = default) => Move(r, CashMovementType.Supply, ct); public Task<CashSessionView> WithdrawAsync(CashOperationRequest r, CancellationToken ct = default) => Move(r, CashMovementType.Withdrawal, ct); private async Task<CashSessionView> Move(CashOperationRequest r, CashMovementType type, CancellationToken ct) { if (r.Amount <= 0 || string.IsNullOrWhiteSpace(r.Reason)) throw new RequestValidationException("Informe valor positivo e motivo."); var s = await Store(ct); await using (s) return await s.MoveAsync(User(), type, r.Amount, r.Reason.Trim(), Version(r.RowVersion), clock.GetUtcNow(), Ctx(), ct); } public async Task<CashSessionView> CloseAsync(CloseCashRequest r, CancellationToken ct = default) { if (r.ClosingAmount < 0) throw new RequestValidationException("Valor de fechamento inválido."); var s = await Store(ct); await using (s) return await s.CloseAsync(User(), r.ClosingAmount, Version(r.RowVersion), clock.GetUtcNow(), Ctx(), ct); } private async Task<ICashStore> Store(CancellationToken ct) { if (current.TenantId is not { } id) throw new ResourceNotFoundException("Tenant não encontrado."); return factory.Create(await resolver.ResolveByTenantIdAsync(id, ct) ?? throw new ResourceNotFoundException("Tenant não encontrado.")); } private Guid User() => current.UserId ?? throw new ResourceNotFoundException("Usuário não encontrado."); private SalesAuditContext Ctx() => new(current.CorrelationId, current.IpAddress); private static byte[] Version(string v) { try { var b = Convert.FromBase64String(v); if (b.Length == 0) throw new FormatException(); return b; } catch (FormatException) { throw new RequestValidationException("Versão do caixa inválida."); } } }
